"""Unit tests for Geopulse Phase 3 MVP: Independent Source Corroboration.Tests the 5 core scenarios required by acceptance review:1. Five publishers repeating one Reuters report -> multiple_reports_shared_origin (1 chain).2. Several publishers citing the same government announcement ->#    multiple_reports_shared_origin (1 chain).3. Two genuinely independent investigations -> independently_corroborated (2 chains).4. One independent report contradicting another -> conflicting_evidence.5. Articles whose original sources cannot be established -> insufficient_information (0 chains).Plus:6. Single-source reporting baseline.7. Syndicated / republished cross-domain lineage.8. Telegram briefing badge and assessment rendering consistency."""import jsonfrom datetime import UTC, datetimefrom geopulse.classification.models import TopicCategoryfrom geopulse.clustering.models import EventClusterfrom geopulse.corroboration.lineage import (    build_cluster_lineages,    extract_article_lineage,)from geopulse.corroboration.service import (    corroborate_claim,    corroborate_event,)from geopulse.delivery.formatter import TelegramDigestFormatterfrom geopulse.ingestion.models import ArticleRecordfrom geopulse.summarization.client import MockOllamaClientfrom geopulse.summarization.models import (    ClaimEvidenceReference,    EventSourceAttribution,    EventSummary,    SummaryClaim,)from geopulse.summarization.service import EventSummarizerdef _make_article(    source_name: str,    title: str,    snippet: str,    url: str,    canonical_url: str | None = None,    body_text: str | None = None,) -> ArticleRecord:    now = datetime(2026, 11, 4, 10, 0, tzinfo=UTC)    return ArticleRecord(        source_name=source_name,        title=title,        snippet=snippet,        url=url,        canonical_url=canonical_url or url,        published_at=now,        fetched_at=now,        body_text=body_text,        content_hash=f"hash-{url}",        relevance_status="relevant",        topic="armed_conflict",    )# ---------------------------------------------------------------------------# 1. Five publishers repeating one Reuters report# ---------------------------------------------------------------------------def test_five_publishers_repeating_one_reuters_report():    """Five distinct outlets republishing or citing one Reuters wire report must collapse    to 1 chain."""    wire_claim = (        "A maritime drone struck an offshore patrol vessel in the Black Sea near Sevastopol."    )    articles = [        _make_article(            source_name="BBC News",            title="Black Sea incident reported",            snippet=(                f"According to Reuters, {wire_claim.lower()} "                "Local authorities confirmed sirens were active."            ),            url="https://bbc.com/news/world-1",        ),        _make_article(            source_name="The Guardian",            title="Drone hits vessel in Black Sea",            snippet=(                f"Citing a report by Reuters, {wire_claim.lower()} "                "No casualties were immediately announced."            ),            url="https://theguardian.com/world/2026/nov/drone",        ),        _make_article(            source_name="CNN",            title="Patrol vessel targeted",            snippet=(                f"(Reuters) - {wire_claim} Naval forces were deployed to secure the harbor area."            ),            url="https://cnn.com/2026/11/04/europe/drone-strike",        ),        _make_article(            source_name="Al Jazeera",            title="Black Sea naval strike",            snippet=(                f"Reuters reported that {wire_claim.lower()} "                "Joint maritime monitoring agencies tracked the impact."            ),            url="https://aljazeera.com/news/2026/11/black-sea-strike",        ),        _make_article(            source_name="Deutsche Welle",            title="Vessel damaged in Black Sea",            snippet=(                f"Per Reuters, {wire_claim.lower()} "                "Emergency rescue operations proceeded under defensive escort."            ),            url="https://dw.com/en/black-sea-drone-attack/a-12345",        ),    ]    # Verify Lineages    lineages = build_cluster_lineages(articles)    for art in articles:        lin = lineages[art.url]        assert lin.lineage_classification == "wire_service_citation"        assert lin.original_source == "Reuters"        assert lin.citation_source == "Reuters"    # Evaluate Claim Corroboration    evidence_refs = tuple(        ClaimEvidenceReference(            source_url=a.url,            evidence_span=wire_claim,            verification_status="accepted",        )        for a in articles    )    claim = SummaryClaim(        claim_id="claim-drone-strike",        text=wire_claim,        evidence_refs=evidence_refs,        classification="reported_fact",        central=True,    )    c_res = corroborate_claim(claim, articles, lineages)    assert c_res.status == "multiple_reports_shared_origin"    assert c_res.independent_evidence_chains == 1    assert c_res.original_sources == ("Reuters",)    assert len(c_res.supporting_articles) == 5    assert len(c_res.derivative_articles) == 5    assert "rely on a single shared wire report (Reuters)" in c_res.explanation    # Evaluate Event Corroboration    now = datetime(2026, 11, 4, 10, 0, tzinfo=UTC)    event = EventCluster(        title="Black Sea Vessel Drone Strike",        category=TopicCategory.ARMED_CONFLICT,        first_seen_at=now,        last_seen_at=now,        articles=tuple(articles),    )    summary = EventSummary(        event_id=event.id,        headline="Naval Drone Targets Patrol Vessel in Black Sea",        what_happened=wire_claim,        confidence_qualification="multiple_reports_shared_origin",        sources=tuple(            EventSourceAttribution(source_name=a.source_name, url=a.url, title=a.title)            for a in articles        ),        claims=(claim,),        model_used="test-model",        corroboration_status=c_res.status,        independent_chains_count=c_res.independent_evidence_chains,    )    ev_res = corroborate_event(event, summary)    assert ev_res.status == "multiple_reports_shared_origin"    assert ev_res.independent_chains_count == 1    assert ev_res.primary_origin == "Reuters"    # Verify Telegram Briefing Presentation    formatter = TelegramDigestFormatter()    html_block = formatter.format_event(        summary=summary,        event=event,        category=event.category,        confidence_label="multiple_reports_shared_origin",        rank=1,        total=1,    )    assert "[SHARED ORIGIN]" in html_block    assert "[CORROBORATED]" not in html_block    assert "Reported across multiple outlets based on a shared wire" in html_block# ---------------------------------------------------------------------------# 2. Several publishers citing the same government announcement# ---------------------------------------------------------------------------def test_several_publishers_citing_same_government_announcement():    """Outlets repeating a Ministry of Defense statement represent 1 official chain."""    stmt_claim = (        "The defense ministry announced the procurement of three modern air-defense batteries."    )    articles = [        _make_article(            source_name="Defense News",            title="Air Defense Batteries Ordered",            snippet=(                "In an official statement on Monday, the Ministry of Defense announced "                f"{stmt_claim.lower()}"            ),            url="https://defensenews.com/procurement/2026/air-defense",        ),        _make_article(            source_name="Janes",            title="New Radar & Missile Acquisition",            snippet=(                f"According to a statement issued by the Ministry of Defence, {stmt_claim.lower()}"            ),            url="https://janes.com/defence-news/procure-radar",        ),        _make_article(            source_name="Breaking Defense",            title="Procurement Contract Confirmed",            snippet=f"Citing a press release by the Ministry of Defense, {stmt_claim.lower()}",            url="https://breakingdefense.com/2026/11/defense-procure",        ),    ]    lineages = build_cluster_lineages(articles)    for art in articles:        lin = lineages[art.url]        assert lin.lineage_classification == "official_statement"        assert lin.original_source == "Ministry of Defense"    evidence_refs = tuple(        ClaimEvidenceReference(            source_url=a.url,            evidence_span=stmt_claim,            verification_status="accepted",        )        for a in articles    )    claim = SummaryClaim(        claim_id="claim-procure",        text=stmt_claim,        evidence_refs=evidence_refs,        classification="reported_fact",        central=True,    )    c_res = corroborate_claim(claim, articles, lineages)    assert c_res.status == "multiple_reports_shared_origin"    assert c_res.independent_evidence_chains == 1    assert c_res.original_sources == ("Ministry of Defense",)    assert len(c_res.supporting_articles) == 3    assert "official announcement (Ministry of Defense)" in c_res.explanation    # Telegram formatting    now = datetime(2026, 11, 4, 10, 0, tzinfo=UTC)    event = EventCluster(        title="Air Defense Procurement",        category=TopicCategory.WEAPONS_PROCUREMENT,        first_seen_at=now,        last_seen_at=now,        articles=tuple(articles),    )    summary = EventSummary(        event_id=event.id,        headline="Procurement of Three Air Defense Batteries Announced",        what_happened=stmt_claim,        confidence_qualification="Official statement.",        sources=tuple(            EventSourceAttribution(source_name=a.source_name, url=a.url, title=a.title)            for a in articles        ),        claims=(claim,),        model_used="test-model",        corroboration_status=c_res.status,    )    formatter = TelegramDigestFormatter()    html_block = formatter.format_event(        summary=summary,        event=event,        category=event.category,        confidence_label="multiple_reports_shared_origin",        rank=1,        total=1,    )    # Either [OFFICIAL ANNOUNCEMENT] or [SHARED ORIGIN]    assert "[OFFICIAL ANNOUNCEMENT]" in html_block or "[SHARED ORIGIN]" in html_block    assert "[CORROBORATED]" not in html_block# ---------------------------------------------------------------------------# 3. Two genuinely independent investigations# ---------------------------------------------------------------------------def test_two_genuinely_independent_investigations():    """Two independent investigations by distinct outlets yield 2 chains and    independently_corroborated."""    investigation_claim = (        "Underground fuel depots were constructed along the northern border staging areas."    )    articles = [        _make_article(            source_name="The Washington Post",            title="Covert Depot Construction Detailed",            snippet=(                "Staff reporters on the ground inspected construction records, field "                "logistics logs, and fuel delivery manifests confirming the underground "                "staging facility."            ),            url="https://washingtonpost.com/investigations/2026/depot-staging",        ),        _make_article(            source_name="The Wall Street Journal",            title="Satellite Analysis Reveals Staging Sites",            snippet=(                "High-resolution commercial satellite imagery analyzed independently by "                "WSJ geospatial researchers revealed extensive subterranean hardened "                "fuel storage."            ),            url="https://wsj.com/world/satellite-fuel-depots-exclusive",        ),    ]    lineages = build_cluster_lineages(articles)    assert lineages[articles[0].url].lineage_classification == "original_reporting"    assert lineages[articles[0].url].original_source == "The Washington Post"    assert lineages[articles[1].url].lineage_classification == "original_reporting"    assert lineages[articles[1].url].original_source == "The Wall Street Journal"    evidence_refs = tuple(        ClaimEvidenceReference(            source_url=a.url,            evidence_span=investigation_claim,            verification_status="accepted",        )        for a in articles    )    claim = SummaryClaim(        claim_id="claim-depots",        text=investigation_claim,        evidence_refs=evidence_refs,        classification="reported_fact",        central=True,    )    c_res = corroborate_claim(claim, articles, lineages)    assert c_res.status == "independently_corroborated"    assert c_res.independent_evidence_chains == 2    assert set(c_res.original_sources) == {"The Washington Post", "The Wall Street Journal"}    assert "Independently corroborated across 2 distinct reporting chains" in c_res.explanation    # Telegram formatting    now = datetime(2026, 11, 4, 10, 0, tzinfo=UTC)    event = EventCluster(        title="Subterranean Depot Construction",        category=TopicCategory.MILITARY_OPERATIONS,        first_seen_at=now,        last_seen_at=now,        articles=tuple(articles),    )    summary = EventSummary(        event_id=event.id,        headline="Subterranean Fuel Depots Identified Along Staging Corridors",        what_happened=investigation_claim,        confidence_qualification="independently_corroborated",        sources=tuple(            EventSourceAttribution(source_name=a.source_name, url=a.url, title=a.title)            for a in articles        ),        claims=(claim,),        model_used="test-model",        corroboration_status=c_res.status,    )    formatter = TelegramDigestFormatter()    html_block = formatter.format_event(        summary=summary,        event=event,        category=event.category,        confidence_label="independently_corroborated",        rank=1,        total=1,    )    assert "[CORROBORATED]" in html_block    assert "Independent reporting from distinct sources" in html_block# ---------------------------------------------------------------------------# 4. One independent report contradicting another# ---------------------------------------------------------------------------def test_contradicting_reports_yield_conflicting_evidence():    """Contradictory accounts trigger conflicting_evidence status."""    articles = [        _make_article(            source_name="Kyiv Independent",            title="Air Defenses Intercept All Drones",            snippet=(                "Air defense forces intercepted all 15 inbound Shahed attack drones "                "with zero impact on industrial infrastructure."            ),            url="https://kyivindependent.com/all-drones-downed",        ),        _make_article(            source_name="TASS",            title="Industrial Power Substation Destroyed",            snippet=(                "High-precision strike drones successfully struck and destroyed the "                "central industrial transmission grid facility."            ),            url="https://tass.com/substation-destroyed",        ),    ]    claim1 = SummaryClaim(        claim_id="claim-intercept",        text="All 15 attack drones were intercepted with zero ground impact.",        evidence_refs=(            ClaimEvidenceReference(                source_url=articles[0].url,                evidence_span="intercepted all 15 inbound Shahed attack drones with zero impact",                verification_status="accepted",            ),        ),        classification="reported_fact",        central=True,    )    claim2 = SummaryClaim(        claim_id="claim-impact",        text="Industrial power substation was destroyed by striking drones.",        evidence_refs=(            ClaimEvidenceReference(                source_url=articles[1].url,                evidence_span=(                    "struck and destroyed the central industrial transmission grid facility"                ),                verification_status="accepted",            ),        ),        classification="disputed_claim",        central=True,    )    lineages = build_cluster_lineages(articles)    c_res = corroborate_claim(claim1, articles, lineages, contradictory_claims=[claim2])    assert c_res.status == "conflicting_evidence"    assert len(c_res.contradictory_evidence) >= 1    assert "Contradictory evidence identified across sources" in c_res.explanation    # Telegram formatting    now = datetime(2026, 11, 4, 10, 0, tzinfo=UTC)    event = EventCluster(        title="Industrial Substation Attack",        category=TopicCategory.ARMED_CONFLICT,        first_seen_at=now,        last_seen_at=now,        articles=tuple(articles),    )    summary = EventSummary(        event_id=event.id,        headline="Contested Strike on Industrial Substation",        what_happened=(            "Opposing claims on whether drone attack was intercepted or destroyed facility."        ),        confidence_qualification="Contested claims; opposing parties provide conflicting accounts.",        sources=tuple(            EventSourceAttribution(source_name=a.source_name, url=a.url, title=a.title)            for a in articles        ),        claims=(claim1, claim2),        model_used="test-model",        corroboration_status=c_res.status,    )    formatter = TelegramDigestFormatter()    html_block = formatter.format_event(        summary=summary,        event=event,        category=event.category,        confidence_label="conflicting_evidence",        rank=1,        total=1,    )    assert "[DISPUTED]" in html_block    assert "Contested claims" in html_block# ---------------------------------------------------------------------------# 5. Articles whose original sources cannot be established# ---------------------------------------------------------------------------def test_articles_whose_original_sources_cannot_be_established():    """Unverified or social media rumors must classify as unknown and NEVER count as independent."""    unverified_claim = (        "Unconfirmed reports claim advanced hypersonic batteries were relocated to maritime silos."    )    articles = [        _make_article(            source_name="Telegram Channel A",            title="Rumors of missile redeployment",            snippet=(                "Unconfirmed reports circulating online claim advanced hypersonic batteries "                "were relocated to maritime silos."            ),            url="https://t.me/intel_feed_1/100",        ),        _make_article(            source_name="Telegram Channel B",            title="Chatter on coastal relocation",            snippet=(                "Social media reports and unverified claims allege coastal redeployment "                "of missile batteries."            ),            url="https://t.me/intel_feed_2/200",        ),    ]    lineages = build_cluster_lineages(articles)    for art in articles:        lin = lineages[art.url]        assert lin.lineage_classification == "unknown"        assert lin.original_source == "Unknown"    evidence_refs = tuple(        ClaimEvidenceReference(            source_url=a.url,            evidence_span=unverified_claim,            verification_status="accepted",        )        for a in articles    )    claim = SummaryClaim(        claim_id="claim-unverified",        text=unverified_claim,        evidence_refs=evidence_refs,        classification="inference",        central=True,    )    c_res = corroborate_claim(claim, articles, lineages)    # Strict rule: independent evidence chains MUST BE 0 for unknown sources    assert c_res.independent_evidence_chains == 0    assert c_res.status == "insufficient_information"    assert len(c_res.unresolved_relationships) == 2    assert "Source provenance unresolved or insufficient evidence" in c_res.explanation    # Telegram formatting    now = datetime(2026, 11, 4, 10, 0, tzinfo=UTC)    event = EventCluster(        title="Unverified Hypersonic Redeployment",        category=TopicCategory.OTHER_GEOPOLITICAL,        first_seen_at=now,        last_seen_at=now,        articles=tuple(articles),    )    summary = EventSummary(        event_id=event.id,        headline="Unconfirmed Reports Allege Hypersonic Silo Redeployment",        what_happened=unverified_claim,        confidence_qualification="Preliminary reporting; unverified.",        sources=tuple(            EventSourceAttribution(source_name=a.source_name, url=a.url, title=a.title)            for a in articles        ),        claims=(claim,),        model_used="test-model",        corroboration_status=c_res.status,    )    formatter = TelegramDigestFormatter()    html_block = formatter.format_event(        summary=summary,        event=event,        category=event.category,        confidence_label="insufficient_information",        rank=1,        total=1,    )    assert "[PRELIMINARY]" in html_block    assert "Preliminary reporting" in html_block# ---------------------------------------------------------------------------# 6. Single-source reporting baseline# ---------------------------------------------------------------------------def test_single_source_reporting_baseline():    """A solitary article with positive correspondent evidence yields single_source and 1 chain."""    art = _make_article(        source_name="Financial Times",        title="Trade Sanctions Proposed",        snippet=(            "FT diplomatic correspondents in Brussels learned that European Commission "            "diplomats drafted a preliminary sanctions package covering chemical exports."        ),        url="https://ft.com/content/sanctions-draft",    )    lineages = build_cluster_lineages([art])    assert lineages[art.url].lineage_classification == "original_reporting"    assert lineages[art.url].original_source == "Financial Times"    claim = SummaryClaim(        claim_id="claim-sanctions",        text="Diplomats drafted a preliminary sanctions package covering chemical exports.",        evidence_refs=(            ClaimEvidenceReference(                source_url=art.url,                evidence_span="drafted a preliminary sanctions package",                verification_status="accepted",            ),        ),        classification="reported_fact",        central=True,    )    c_res = corroborate_claim(claim, [art], lineages)    assert c_res.status == "single_source"    assert c_res.independent_evidence_chains == 1    assert c_res.original_sources == ("Financial Times",)    assert "Single-source reporting from Financial Times" in c_res.explanation# ---------------------------------------------------------------------------# 7. Syndicated / republished cross-domain lineage# ---------------------------------------------------------------------------def test_syndicated_republished_cross_domain_lineage():    """MSN or aggregator carrying a Politico story is classified as syndicated."""    art = _make_article(        source_name="MSN",        title="Cabinet Reshuffle Expected",        snippet=(            "Syndicated from Politico. Prime Minister prepares senior cabinet adjustments "            "following budget stalemate."        ),        url="https://msn.com/en-us/news/world/cabinet-reshuffle",        canonical_url="https://politico.eu/article/cabinet-reshuffle",    )    lineage = extract_article_lineage(art)    assert lineage.lineage_classification == "syndicated"    assert (        "Politico" in lineage.original_source or "politico" in lineage.canonical_origin_url.lower()    )# ---------------------------------------------------------------------------# 8. Different publishers alone without positive evidence do NOT establish independence# ---------------------------------------------------------------------------def test_different_publishers_without_positive_evidence_do_not_establish_independence():    """Two different publishers reporting without attribution or positive evidence    must both classify as unknown and contribute 0 independent chains (insufficient_information).    """    claim_text = "Regional regulators plan new restrictions on synthetic export transactions."    art1 = _make_article(        source_name="Outlet Alpha",        title="Regulators Plan Export Curbs",        snippet=(            "Regional regulators plan new restrictions on synthetic export transactions "            "next quarter."        ),        url="https://outletalpha.com/news/export-curbs",    )    art2 = _make_article(        source_name="Outlet Beta",        title="Trade Restrictions Considered",        snippet=(            "New restrictions on synthetic export transactions are being considered by regulators."        ),        url="https://outletbeta.com/article/trade-curbs",    )    lineages = build_cluster_lineages([art1, art2])    assert lineages[art1.url].lineage_classification == "unknown"    assert lineages[art2.url].lineage_classification == "unknown"    evidence_refs = (        ClaimEvidenceReference(            source_url=art1.url,            evidence_span="plan new restrictions on synthetic export transactions",            verification_status="accepted",        ),        ClaimEvidenceReference(            source_url=art2.url,            evidence_span="restrictions on synthetic export transactions are being considered",            verification_status="accepted",        ),    )    claim = SummaryClaim(        claim_id="claim-curbs",        text=claim_text,        evidence_refs=evidence_refs,        classification="reported_fact",        central=True,    )    c_res = corroborate_claim(claim, [art1, art2], lineages)    # Strict conservative rule: independent evidence chains MUST BE 0    assert c_res.independent_evidence_chains == 0    assert c_res.status == "insufficient_information"    assert len(c_res.unresolved_relationships) == 2# ---------------------------------------------------------------------------# 9. Persistence and reload of event and claim corroboration data# ---------------------------------------------------------------------------def test_corroboration_persistence_and_reload():    """Verify that event and claim corroboration data, along with briefing_event_evidence    lineage_type and original_source, survive persistence and reload.    """    import uuid    from geopulse.delivery.repository import InMemoryDeliveryRepository    from geopulse.summarization.models import reconstruct_event_summary    now = datetime(2026, 11, 4, 10, 0, tzinfo=UTC)    wire_claim = (        "A maritime drone struck an offshore patrol vessel in the Black Sea near Sevastopol."    )    art1 = _make_article(        source_name="BBC News",        title="Black Sea incident reported",        snippet=f"According to Reuters, {wire_claim.lower()}",        url="https://bbc.com/news/world-1",    )    art2 = _make_article(        source_name="CNN",        title="Patrol vessel targeted",        snippet=f"(Reuters) - {wire_claim}",        url="https://cnn.com/2026/11/04/europe/drone-strike",    )    event = EventCluster(        title="Black Sea Vessel Drone Strike",        category=TopicCategory.ARMED_CONFLICT,        first_seen_at=now,        last_seen_at=now,        articles=(art1, art2),    )    lineages = build_cluster_lineages([art1, art2])    claim = SummaryClaim(        claim_id="claim-wire-strike",        text=wire_claim,        evidence_refs=(            ClaimEvidenceReference(                source_url=art1.url,                evidence_span=wire_claim,                verification_status="accepted",            ),            ClaimEvidenceReference(                source_url=art2.url,                evidence_span=wire_claim,                verification_status="accepted",            ),        ),        classification="reported_fact",        central=True,    )    c_res = corroborate_claim(claim, [art1, art2], lineages)    summary = EventSummary(        event_id=event.id,        headline="Naval Drone Targets Patrol Vessel in Black Sea",        what_happened=wire_claim,        confidence_qualification="multiple_reports_shared_origin",        sources=(            EventSourceAttribution(source_name=art1.source_name, url=art1.url, title=art1.title),            EventSourceAttribution(source_name=art2.source_name, url=art2.url, title=art2.title),        ),        claims=(            claim.model_copy(                update={                    "corroboration_status": c_res.status,                    "independent_chains_count": c_res.independent_evidence_chains,                    "corroboration_explanation": c_res.explanation,                }            ),        ),        model_used="test-model",        corroboration_status=c_res.status,        independent_chains_count=c_res.independent_evidence_chains,    )    class DummyResult:        def __init__(self, ev, summ):            self.event = ev            self.summary = summ    repo = InMemoryDeliveryRepository()    briefing_id = str(uuid.uuid4())    url_to_id = {art1.canonical_url: "art-uuid-1", art2.canonical_url: "art-uuid-2"}    ev_count, evi_count = repo.record_briefing_events(        briefing_id=briefing_id,        results=[DummyResult(event, summary)],        article_url_to_id=url_to_id,    )    assert ev_count == 1    assert evi_count == 2    # 1. Verify retrieval of briefing_event_evidence with lineage_type and original_source    evidence_records = repo.get_briefing_event_evidence(briefing_id=briefing_id, event_id=event.id)    assert len(evidence_records) == 2    for r in evidence_records:        assert r["lineage_type"] == "wire_service_citation"        assert r["original_source"] == "Reuters"    # 2. Verify reconstruction of EventSummary from stored row    stored_event_row = repo._briefing_events[briefing_id][0]    reconstructed = reconstruct_event_summary(stored_event_row)    assert reconstructed is not None    assert reconstructed.corroboration_status == "multiple_reports_shared_origin"    assert reconstructed.independent_chains_count == 1    assert len(reconstructed.claims) == 1    reconstructed_claim = reconstructed.claims[0]    assert reconstructed_claim.corroboration_status == "multiple_reports_shared_origin"    assert reconstructed_claim.independent_chains_count == 1def test_cluster_level_corroboration_fallback_prevents_overstating_corroboration():    """Verify cluster-level fallback without claims never overstates corroboration.    1. Disputed events with multiple independent origins must evaluate to conflicting_evidence.    2. Single-source clustered events must never be promoted to independently_corroborated.    3. Multiple articles sharing a wire must evaluate to multiple_reports_shared_origin.    4. Only genuinely corroborated events with 2+ independent origins       evaluate to independently_corroborated.    """    now = datetime(2026, 11, 4, 12, 0, tzinfo=UTC)    art_reuters = ArticleRecord(        source_name="Reuters",        title="Armed clashes reported near strategic intersection",        url="https://reuters.com/clashes-1",        canonical_url="https://reuters.com/clashes-1",        published_at=now,        snippet="By John Doe in Kyiv. Reuters correspondent reports clashes near the intersection.",        author="John Doe",        content_hash="hash-reuters-1",    )    art_ap = ArticleRecord(        source_name="Associated Press",        title="Ministry denies clashes, reporting area remains quiet",        url="https://apnews.com/clashes-2",        canonical_url="https://apnews.com/clashes-2",        published_at=now,        snippet="By Jane Smith in Moscow. AP correspondent reports the ministry denies all claims.",        author="Jane Smith",        content_hash="hash-ap-1",    )    # 1. Disputed event with 2 independent journalists must be    # conflicting_evidence, not corroborated    ev_disputed = EventCluster(        title="Contested Clashes at Intersection",        category=TopicCategory.ARMED_CONFLICT,        first_seen_at=now,        last_seen_at=now,        confidence_label="disputed",        articles=(art_reuters, art_ap),    )    summary_no_claims = EventSummary(        event_id=ev_disputed.id,        headline="Contested Clashes at Intersection",        what_happened=(            "Opposing claims over whether clashes occurred at the strategic intersection."        ),        confidence_qualification="Contested claims between parties.",        model_used="test-model",        claims=(),    )    res_disputed = corroborate_event(ev_disputed, summary_no_claims)    assert res_disputed.status == "conflicting_evidence"    assert res_disputed.status != "independently_corroborated"    # 2. Single-source event must remain single_source, never promoted    ev_single = EventCluster(        title="Clashes at Intersection",        category=TopicCategory.ARMED_CONFLICT,        first_seen_at=now,        last_seen_at=now,        confidence_label="single_source",        articles=(art_reuters,),    )    res_single = corroborate_event(ev_single, summary_no_claims)    assert res_single.status == "single_source"    assert res_single.independent_chains_count == 1    # 3. Two articles repeating same wire must be multiple_reports_shared_origin (1 chain)    art_yahoo = ArticleRecord(        source_name="Yahoo News",        title="Armed clashes reported",        url="https://finance.yahoo.com/clashes",        canonical_url="https://finance.yahoo.com/clashes",        published_at=now,        snippet="(Reuters) - Clashes were reported near the intersection.",        content_hash="hash-yahoo-1",    )    ev_shared = EventCluster(        title="Clashes at Intersection",        category=TopicCategory.ARMED_CONFLICT,        first_seen_at=now,        last_seen_at=now,        confidence_label="corroborated",        articles=(art_reuters, art_yahoo),    )    res_shared = corroborate_event(ev_shared, summary_no_claims)    assert res_shared.status == "multiple_reports_shared_origin"    assert res_shared.independent_chains_count == 1    # 4. Two genuinely independent articles with confirmed corroboration label ->    # independently_corroborated    ev_corrob = EventCluster(        title="Clashes at Intersection",        category=TopicCategory.ARMED_CONFLICT,        first_seen_at=now,        last_seen_at=now,        confidence_label="corroborated",        articles=(art_reuters, art_ap),    )    res_corrob = corroborate_event(ev_corrob, summary_no_claims)    assert res_corrob.status == "independently_corroborated"    assert res_corrob.independent_chains_count == 2def test_two_independent_articles_without_claims_cannot_produce_corroborated():    """Verify that summarize_event with two independent articles but without claims    CANNOT produce [CORROBORATED], strictly defaulting to unassessed (0 chains).    Proves:    1. Independent articles without structured claim evidence default to unassessed (0 chains)       and render [NOT ASSESSED], not [CORROBORATED].    2. Shared origin / wire articles without claims preserve multiple_reports_shared_origin       and render [SHARED ORIGIN].    3. Verified claim-level evidence across independent sources produces       independently_corroborated and renders [CORROBORATED].    """    now = datetime(2026, 11, 4, 12, 0, tzinfo=UTC)    art_reuters = ArticleRecord(        source_name="Reuters",        title="Naval patrol forces deploy along strategic shipping lane",        url="https://reuters.com/naval-patrol-deploy",        canonical_url="https://reuters.com/naval-patrol-deploy",        published_at=now,        snippet=(            "By John Doe in Constanta. Reuters correspondent reports naval patrol forces deployed."        ),        author="John Doe",        content_hash="hash-reuters-patrol",    )    art_ap = ArticleRecord(        source_name="Associated Press",        title="Patrol vessels monitor commercial transit corridors",        url="https://apnews.com/patrol-vessels-monitor",        canonical_url="https://apnews.com/patrol-vessels-monitor",        published_at=now,        snippet=(            "By Jane Smith in Varna. AP correspondent reports patrol vessels began monitoring "            "transit routes."        ),        author="Jane Smith",        content_hash="hash-ap-patrol",    )    ev_independent = EventCluster(        title="Naval Patrol Forces Deploy Along Shipping Lane",        category=TopicCategory.MILITARY_OPERATIONS,        first_seen_at=now,        last_seen_at=now,        confidence_label="corroborated",        articles=(art_reuters, art_ap),    )    raw_output = {        "headline": "Naval Patrol Forces Deploy Along Shipping Lane",        "what_happened": (            "Naval patrol vessels began monitoring commercial transit corridors along the route."        ),        "key_details": {            "actors": ["Naval patrol forces"],            "location": "Shipping lane",            "timing": "Morning",            "action": "deploy patrol vessels",        },        "significance": "Secures merchant traffic across the corridor.",        "confidence_qualification": "Independent reporting from distinct sources.",    }    # 1. summarize_event with two independent articles but NO claims    summarizer = EventSummarizer(client=MockOllamaClient(canned_response=json.dumps(raw_output)))    res = summarizer.summarize_event(ev_independent)    assert res.status == "success", res.quarantine_reason    assert res.summary is not None    assert len(res.summary.claims) == 0    # Corroboration status must NOT be independently_corroborated    assert res.summary.corroboration_status == "unassessed"    assert res.summary.independent_chains_count == 0    # Telegram formatting must render [NOT ASSESSED], never [CORROBORATED]    formatter = TelegramDigestFormatter()    rendered_block = formatter.format_event_block(        summary=res.summary,        category=ev_independent.category,        confidence_label=ev_independent.confidence_label,        rank=1,        total=1,    )    assert "[NOT ASSESSED]" in rendered_block    assert "[CORROBORATED]" not in rendered_block    # 2. Shared-origin / wire reports without claims preserve multiple_reports_shared_origin    art_wire_copy = ArticleRecord(        source_name="Yahoo News",        title="Naval patrol forces deploy along shipping lane",        url="https://finance.yahoo.com/naval-patrol-copy",        canonical_url="https://finance.yahoo.com/naval-patrol-copy",        published_at=now,        snippet="(Reuters) - Naval patrol vessels deployed to monitor commercial transit routes.",        content_hash="hash-yahoo-patrol",    )    ev_wire = EventCluster(        title="Naval Patrol Forces Deploy Along Shipping Lane",        category=TopicCategory.MILITARY_OPERATIONS,        first_seen_at=now,        last_seen_at=now,        confidence_label="corroborated",        articles=(art_reuters, art_wire_copy),    )    res_wire = summarizer.summarize_event(ev_wire)    assert res_wire.status == "success", res_wire.quarantine_reason    assert res_wire.summary is not None    assert res_wire.summary.corroboration_status == "multiple_reports_shared_origin"    assert res_wire.summary.independent_chains_count == 1    rendered_wire = formatter.format_event_block(        summary=res_wire.summary,        category=ev_wire.category,        confidence_label=ev_wire.confidence_label,        rank=1,        total=1,    )    assert "[SHARED ORIGIN]" in rendered_wire    assert "[CORROBORATED]" not in rendered_wire    # 3. With verified claim-level evidence across independent sources ->    # independently_corroborated    claim_verified = SummaryClaim(        claim_id="claim-patrol-1",        text=(            "Naval patrol vessels began monitoring commercial transit corridors along the route."        ),        evidence_refs=(            ClaimEvidenceReference(                source_url=art_reuters.url,                evidence_span="naval patrol forces deployed",                verification_status="accepted",            ),            ClaimEvidenceReference(                source_url=art_ap.url,                evidence_span="patrol vessels began monitoring transit routes",                verification_status="accepted",            ),        ),        classification="reported_fact",        central=True,    )    lineages_map = build_cluster_lineages(ev_independent.articles)    c_corrob = corroborate_claim(claim_verified, ev_independent.articles, lineages_map)    assert c_corrob.status == "independently_corroborated"    assert c_corrob.independent_evidence_chains == 2    corroborated_summary = res.summary.model_copy(        update={            "claims": (claim_verified,),            "corroboration_status": "independently_corroborated",            "independent_chains_count": 2,        }    )    rendered_corrob = formatter.format_event_block(        summary=corroborated_summary,        category=ev_independent.category,        confidence_label=ev_independent.confidence_label,        rank=1,        total=1,    )    assert "[CORROBORATED]" in rendered_corrob    assert "[NOT ASSESSED]" not in rendered_corrob